// Only the migration container receives the owner credentials.
import { spawnSync } from "node:child_process";
import pg from "pg";
const password = process.env.CRM_APP_PASSWORD;
if (!/^[a-fA-F0-9]{64}$/.test(password || "")) {
  throw new Error(
    "CRM_APP_PASSWORD must be a 64-character hex string generated by deploy/configure.sh",
  );
}
const migration = spawnSync(process.execPath, ["server/migrate.js"], {
  stdio: "inherit",
});
if (migration.status !== 0) process.exit(migration.status || 1);
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
try {
  await pool.query(
    `DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='crm_app') THEN CREATE ROLE crm_app LOGIN; END IF; END $$`,
  );
  // The strict hex validation above makes this role password literal safe.
  await pool.query(
    `ALTER ROLE crm_app WITH PASSWORD '${password}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS`,
  );
  await pool.query("GRANT CONNECT ON DATABASE crm_module TO crm_app");
  await pool.query("GRANT USAGE ON SCHEMA public TO crm_app");
  await pool.query(
    "GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO crm_app",
  );
  await pool.query(
    "GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO crm_app",
  );
  await pool.query(
    "ALTER DEFAULT PRIVILEGES FOR ROLE crm_owner IN SCHEMA public GRANT SELECT,INSERT,UPDATE,DELETE ON TABLES TO crm_app",
  );
  await pool.query(
    "ALTER DEFAULT PRIVILEGES FOR ROLE crm_owner IN SCHEMA public GRANT USAGE,SELECT ON SEQUENCES TO crm_app",
  );
  console.log("CRM schema and restricted application database role are ready.");
} finally {
  await pool.end();
}
